grid[18].insert(20,6)
H,W=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  v=grid[r][c]
  if v==6 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c));cells=[]
  while q:
   a,b=q.pop();cells.append((a,b))
   for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
    if 0<=x<H and 0<=y<W and grid[x][y]==v and (x,y) not in seen: seen.add((x,y));q.append((x,y))
  comps.append((v,cells))
def norm(cells):
 r0=min(r for r,c in cells);c0=min(c for r,c in cells)
 return tuple(sorted((r-r0,c-c0) for r,c in cells))
for i,(v,cells) in enumerate(comps): print(i,v,len(cells),(min(r for r,c in cells),min(c for r,c in cells)),norm(cells))
